package studio

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"strings"
)

// VisualAnchor defines an immutable physical and contextual ground truth
// for character, face, wardrobe, environment, and cinematography across all scenes
// generated by disparate AI adapters (Google Flow, Veo, Gemini, Muse AI, Pollinations, Claude, ChatGPT, Grok).
type VisualAnchor struct {
	ActorName         string `json:"actor_name"`
	Gender            string `json:"gender"`
	Age               int    `json:"age"`
	Ethnicity         string `json:"ethnicity"`
	FaceTraits        string `json:"face_traits"`
	Hairstyle         string `json:"hairstyle"`
	Wardrobe          string `json:"wardrobe"`
	Environment       string `json:"environment"`
	Lighting          string `json:"lighting"`
	FilmStock         string `json:"film_stock"`
	DeterministicSeed int64  `json:"deterministic_seed"`
	MasterPhotoPath   string `json:"master_photo_path,omitempty"`
}

// NewVisualAnchor synthesizes a cohesive, photorealistic visual anchor profile
// tailored to the requested topic, genre, and user model photo.
// Defaults strictly to Vietnamese or Chinese personas with photorealistic East Asian features.
func NewVisualAnchor(topic, genre, niche, userModelPhoto string) *VisualAnchor {
	genreLow := strings.ToLower(genre)
	topicLow := strings.ToLower(topic)

	// Derive a stable deterministic seed based on topic and genre
	h := sha256.Sum256([]byte(topic + "|" + genre + "|" + niche))
	seed := int64(binary.BigEndian.Uint64(h[:8]) & 0x7FFFFFFFFFFFFFFF)

	anchor := &VisualAnchor{
		DeterministicSeed: seed,
		MasterPhotoPath:   userModelPhoto,
		FilmStock:         "Arri Alexa 35 cinema camera with Cooke Panchro 35mm anamorphic prime lens, Kodak Vision3 500T organic film grain, natural color science",
	}

	isChinese := strings.Contains(topicLow, "trung quốc") ||
		strings.Contains(topicLow, "douyin") ||
		strings.Contains(topicLow, "hoa ngữ") ||
		strings.Contains(topicLow, "c-biz") ||
		strings.Contains(topicLow, "cbiz") ||
		strings.Contains(genreLow, "douyin") ||
		strings.Contains(strings.ToLower(niche), "cn")

	isFairyBeauty := strings.Contains(topicLow, "thần tiên tỉ tỉ") ||
		strings.Contains(topicLow, "than tien ti ti") ||
		strings.Contains(topicLow, "tiên tỉ tỉ") ||
		strings.Contains(topicLow, "tiên nữ") ||
		strings.Contains(topicLow, "xinh đẹp") ||
		strings.Contains(topicLow, "mỹ nhân") ||
		strings.Contains(genreLow, "fairy") ||
		strings.Contains(genreLow, "beauty") ||
		strings.Contains(strings.ToLower(niche), "fairy")

	if isFairyBeauty {
		anchor.ActorName = "Ngọc Tiên"
		anchor.Gender = "female"
		anchor.Age = 21
		anchor.Ethnicity = "Vietnamese"
		anchor.FaceTraits = "extraordinarily gorgeous, breathtakingly beautiful young Vietnamese woman with radiant luminous porcelain skin, captivating bright hazel almond eyes, delicate charming jawline, sweet mesmerizing smile, ethereal heavenly facial beauty"
		anchor.Hairstyle = "silky waist-length dark hair styled in soft graceful waves, fluttering gently"
		anchor.Wardrobe = "chic modern aesthetic pastel silk outfit with flowing elegant lines"
		anchor.Environment = "aesthetic sunlit luxury studio with soft sheer curtains and subtle pastel floral accents"
		anchor.Lighting = "dreamy soft beauty key light with warm golden rim light highlighting hair and silhouette"
	} else if isChinese {
		if strings.Contains(genreLow, "dance") || strings.Contains(topicLow, "dance") || strings.Contains(genreLow, "vũ đạo") {
			anchor.ActorName = "Mei Ling"
			anchor.Gender = "female"
			anchor.Age = 22
			anchor.Ethnicity = "Chinese"
			anchor.FaceTraits = "breathtaking Chinese Douyin visual, delicate East Asian facial features, porcelain skin, captivating almond eyes, subtle natural makeup"
			anchor.Hairstyle = "silky waist-length dark hair styled in modern loose Douyin waves"
			anchor.Wardrobe = "contemporary Douyin trending dance outfit with sleek modern silhouette and subtle metallic details"
			anchor.Environment = "aesthetic high-end neon studio in Shanghai with soft floor reflections and ambient purple-cyan rim light"
			anchor.Lighting = "crisp beauty lighting with soft 5600K key and stylish neon ambient backlights"
		} else {
			anchor.ActorName = "Xiao Chen"
			anchor.Gender = "female"
			anchor.Age = 24
			anchor.Ethnicity = "Chinese"
			anchor.FaceTraits = "elegant refined East Asian facial structure, clear porcelain complexion, expressive dark brown eyes"
			anchor.Hairstyle = "sleek shoulder-length jet-black hair with clean center part"
			anchor.Wardrobe = "minimalist designer tailored outfit in muted pastel tones"
			anchor.Environment = "modern penthouse in Beijing with architectural wood and floor-to-ceiling panoramic glass"
			anchor.Lighting = "natural cinematic window daylight balanced with warm 3500K interior accents"
		}
	} else if strings.Contains(genreLow, "dance") || strings.Contains(topicLow, "dance") || strings.Contains(genreLow, "vũ đạo") {
		anchor.ActorName = "Linh"
		anchor.Gender = "female"
		anchor.Age = 23
		anchor.Ethnicity = "Vietnamese"
		anchor.FaceTraits = "striking almond-shaped dark hazel eyes, high cheekbones, delicate jawline, warm radiant porcelain skin, natural subtle lip tint"
		anchor.Hairstyle = "glossy long jet-black hair with soft loose waves flowing gracefully over shoulders"
		anchor.Wardrobe = "tailored modern athleisure corset top in matte obsidian black with metallic silver piping accents, high-waisted stylish cargo joggers"
		anchor.Environment = "aesthetic high-ceiling minimalist dance studio with polished light oak hardwood floor reflecting warm softbox highlights, subtle floor-level warm neon tube accents"
		anchor.Lighting = "diffused 5600K cinematic key light overhead, warm 3200K amber rim lighting separating subject from deep background, soft atmospheric haze"
	} else if strings.Contains(niche, "fashion") || strings.Contains(genreLow, "fashion") || strings.Contains(topicLow, "thời trang") {
		anchor.ActorName = "Mai"
		anchor.Gender = "female"
		anchor.Age = 25
		anchor.Ethnicity = "Vietnamese"
		anchor.FaceTraits = "refined elegant features, defined facial contour, expressive warm brown eyes, natural glowing skin texture"
		anchor.Hairstyle = "chic shoulder-length wavy chestnut brown hair neatly styled with a clean side part"
		anchor.Wardrobe = "structured ivory cream tailored blazer over a silk minimalist camisole, minimalist fine silver earrings"
		anchor.Environment = "contemporary luxury boutique loft in Da Nang with floor-to-ceiling panoramic glass windows overlooking tropical greenery, architectural concrete and warm wood"
		anchor.Lighting = "gentle morning diffused daylight, soft golden-hour bounce light, 5400K natural neutral white"
	} else if strings.Contains(genreLow, "tình yêu") || strings.Contains(genreLow, "ngôn tình") || strings.Contains(genreLow, "anime") || strings.Contains(topicLow, "tình yêu") || strings.Contains(topicLow, "thanh xuân") || strings.Contains(topicLow, "học đường") {
		anchor.ActorName = "Minh & An"
		anchor.Gender = "couple"
		anchor.Age = 18
		anchor.Ethnicity = "Anime"
		anchor.FaceTraits = "breathtaking Makoto Shinkai style romantic anime aesthetics, gorgeous anime boy with expressive warm eyes and cute blushing anime girl with long silky hair"
		anchor.Hairstyle = "detailed anime styled dark hair with glowing soft highlights"
		anchor.Wardrobe = "charming high school uniforms with crisp white shirts and navy accents"
		anchor.Environment = "stunning nostalgic high school campus, sparkling rain drops, lush green trees and blossoming flowers"
		anchor.Lighting = "dreamy atmospheric anime lighting with glowing lens flares, vibrant sunset and soft pastel sky"
		anchor.FilmStock = "Makoto Shinkai & CoMix Wave 4K anime cinematic masterpiece, rich hand-painted background art, vibrant anime aesthetic"
	} else if strings.Contains(genreLow, "kinh doanh") || strings.Contains(topicLow, "tài chính") || strings.Contains(topicLow, "business") {
		anchor.ActorName = "Minh"
		anchor.Gender = "male"
		anchor.Age = 28
		anchor.Ethnicity = "Vietnamese"
		anchor.FaceTraits = "sharp masculine jawline, focused intelligent dark eyes, confident poised demeanor, smooth groomed complexion"
		anchor.Hairstyle = "clean modern side-part fade cut, neatly textured dark hair"
		anchor.Wardrobe = "crisp bespoke midnight navy blazer over an open-collar sky-blue oxford shirt, slim luxury wristwatch with leather strap"
		anchor.Environment = "modern penthouse executive workspace, marble conference table, warm walnut acoustic wood slatted wall, city skyline bokeh"
		anchor.Lighting = "cinematic high-contrast Rembrandt lighting, subtle 3500K warm desk lamp accent, cold exterior twilight contrast"
	} else {
		anchor.ActorName = "An"
		anchor.Gender = "female"
		anchor.Age = 24
		anchor.Ethnicity = "Vietnamese"
		anchor.FaceTraits = "approachable radiant smile, expressive deep brown eyes, natural gentle bone structure, clear authentic skin"
		anchor.Hairstyle = "natural shoulder-length dark brown hair with soft natural movement"
		anchor.Wardrobe = "stylish minimalist beige ribbed knit sweater, delicate silver pendant necklace"
		anchor.Environment = "cozy warm aesthetic sunlit interior, minimal Scandinavian furniture, lush monstera potted plant, warm beige linen curtains"
		anchor.Lighting = "soft window daylight from the side, 45-degree diffused key light, natural warm ambience"
	}

	return anchor
}

// MasterPortraitPrompt produces the ground truth keyframe generation prompt (Scene 0).
func (a *VisualAnchor) MasterPortraitPrompt(aspectRatio string) string {
	if a == nil {
		return "Cinematic masterpiece portrait of East Asian person, photorealistic, 8k resolution, no text, no watermark"
	}
	aspectDesc := "vertical 9:16 portrait composition"
	if aspectRatio == "16:9" {
		aspectDesc = "horizontal 16:9 cinematic widescreen composition"
	}

	refLock := ""
	if a.MasterPhotoPath != "" {
		refLock = " Strictly conditioned on the uploaded character reference image, preserving 100% identical facial geometry, eyes, nose, lips and facial contour."
	}

	return fmt.Sprintf("Masterclass photorealistic portrait of %s, a %d-year-old %s %s with %s and %s, wearing signature %s.%s Standing in %s. Masterfully illuminated by %s. Shot on %s, %s, f/1.8 shallow depth of field, authentic micro skin texture and natural pores, crisp eye reflections, clean cinematic color grade, 8k resolution, photorealistic film still, completely clean frame, no text, no watermark, no 3D render, no CGI artifacts.",
		a.ActorName, a.Age, a.Ethnicity, a.Gender, a.FaceTraits, a.Hairstyle, a.Wardrobe, refLock,
		a.Environment, a.Lighting, a.FilmStock, aspectDesc)
}

// EnrichScenePrompt injects the complete physical continuity identity into any scene prompt.
func (a *VisualAnchor) EnrichScenePrompt(actionDescription, cameraMotion string, sceneIndex, totalScenes int) string {
	if a == nil {
		return actionDescription + ", cinematic photorealistic 8k, no text, no watermark"
	}

	if cameraMotion == "" {
		cameraMotion = "smooth cinematic steadycam tracking with subtle parallax"
	}

	refLock := ""
	if a.MasterPhotoPath != "" {
		refLock = " Strictly locked to the reference character photo with 100% identical facial features and appearance."
	}

	if a.Ethnicity == "Anime" {
		return fmt.Sprintf("Single vertical full-frame composition (scene %d of %d), breathtaking romantic anime illustration: %s. %s with %s, wearing %s. Setting: %s. Atmosphere: %s. Art style: %s, 8k resolution, Makoto Shinkai anime aesthetic, vibrant vivid colors, clean single shot, no split screen, no collage, no panels, strictly no text, no subtitles, no watermark.",
			sceneIndex, totalScenes, actionDescription, a.FaceTraits, a.Hairstyle, a.Wardrobe, a.Environment, a.Lighting, a.FilmStock)
	}

	return fmt.Sprintf("Single vertical full-frame cinematic shot (scene %d of %d) featuring %s, the exact same %d-year-old %s %s with identical facial features (%s), same %s, and wearing the same %s.%s Action: %s. Setting: %s. Lighting: consistent %s. Camera movement: %s. Captured on %s, f/1.8 lens, perfect character and environmental continuity, no visual drift, photorealistic, 8k resolution, authentic skin texture, strictly clean single frame, no split screen, no collage, no text, no subtitles, no watermark.",
		sceneIndex, totalScenes, a.ActorName, a.Age, a.Ethnicity, a.Gender,
		a.FaceTraits, a.Hairstyle, a.Wardrobe, refLock,
		actionDescription, a.Environment, a.Lighting, cameraMotion, a.FilmStock)
}

// FlowPrompt formats a prompt optimized specifically for Google Flow (Veo SD 480p) text-to-video / image-to-video engine.
func (a *VisualAnchor) FlowPrompt(actionDescription, cameraMotion string) string {
	if a == nil {
		return actionDescription + ", photorealistic cinematic, 480p smooth motion"
	}
	if cameraMotion == "" {
		cameraMotion = "smooth slow cinematic push-in"
	}
	return fmt.Sprintf("%s, featuring %s (%s, %s, wearing %s) in %s. Camera: %s. Photorealistic cinematic lighting, authentic motion, no morphing, no artifacts.",
		actionDescription, a.ActorName, a.FaceTraits, a.Hairstyle, a.Wardrobe, a.Environment, cameraMotion)
}
